const NEW = ['save-load-and-versioned-format','item-and-module-database','emitter-state-and-light-exposure-query','failure-and-trail-system','2d-lighting-and-occlusion','interaction-system','suit-and-equipment','ship-section-and-layout-data-model','ship-body-and-interior-physics','derelict-authoring-handmade-kits','attention-system','modular-ship-assembly','web-map-and-transit','horror-entities','sanity-and-hallucination-rules','boarding-and-salvage','perception-filter','chart-table-web-map-and-menus','adaptive-audio-and-tells','hud-and-suit-layer','in-world-instruments-and-inspect-view','debug-overlay-true-values']
const OLD = ['command-simulation-layer','pixel-perfect-render-pipeline-camera','player-controller-input','life-support-graph']
const ALL = OLD.concat(NEW)
const P = s => `design/gdd/${s}.md`
const SON = { model: 'sonnet', effort: 'high' }
const OPUS = { model: 'opus' }

const COMMON = `PROJECT: The Synaptic Sea (Godot 4.7.2 GDScript, 2D HD-pixel-art co-op survival horror). Repo root ${ROOT} (Bash: cd /d/the-synaptic-sea-2d). Mode: autonomous + full rigor — do not ask questions; decide by the rules below and record what you decided in your return value.
CONTEXT: 26 system GDDs live in design/gdd/ (each 150-370 KB). The 22 newest were authored yesterday by a workflow whose authors could NOT edit other GDDs or the registry directly, so cross-GDD asks piled up as "must repeat"/"routed"/"owed"/"ask" notes, and each system's final advisor review was never applied. design/registry/entities.yaml (757 entries; sections entities/items/formulas/constants) is the single source of truth: an entry's source: GDD owns the value; referenced_by lists readers.
READ RULES: a hook refuses whole-file Read of any file over 40 KB. Find headings with Grep (pattern "^#", output_mode content) and Read by offset/limit. Never read a whole GDD.
WRITE RULES: Edit only the file(s) this task names. Never edit systems-index.md, production/session-state/*, other GDDs, or anything in git; never commit. Keep each GDD's heading set and order. Locked registry values are never changed in a GDD that is not the entry's source; such a GDD's text moves to the registry value. Amendments to the four pre-workflow GDDs (command-simulation-layer, pixel-perfect-render-pipeline-camera, player-controller-input, life-support-graph) carry an inline marker "*(Amended ${DATE} — consistency pass, routed from <gdd>)*". Prefer precise edits over rewrites; preserve numbers that are not in question. Use Bash + python scripts in ${SCR}/tail/work/ for multi-edit patches only if each replacement prints its match count; otherwise the Edit tool.`

const ASK = { type: 'object', properties: { target: { type: 'string' }, ask: { type: 'string' }, source_location: { type: 'string' } }, required: ['target', 'ask', 'source_location'] }
const REGREQ = { type: 'object', properties: { name: { type: 'string' }, change: { type: 'string' }, reason: { type: 'string' } }, required: ['name', 'change', 'reason'] }
const CLOSE_S = { type: 'object', properties: { applied: { type: 'array', items: { type: 'string' } }, skipped: { type: 'array', items: { type: 'string' } }, registry_requests: { type: 'array', items: REGREQ }, outbound_asks: { type: 'array', items: ASK } }, required: ['applied', 'skipped', 'registry_requests', 'outbound_asks'] }
const FIND = { type: 'object', properties: { kind: { type: 'string', enum: ['CONFLICT', 'STALE_REGISTRY', 'NAME_MISSING', 'UNLISTED_REF', 'LISTED_UNUSED'] }, name: { type: 'string' }, target_file: { type: 'string' }, location: { type: 'string' }, registry_value: { type: 'string' }, gdd_value: { type: 'string' }, fix: { type: 'string' } }, required: ['kind', 'name', 'target_file', 'location', 'registry_value', 'gdd_value', 'fix'] }
const FIND_S = { type: 'object', properties: { findings: { type: 'array', items: FIND }, entries_checked: { type: 'number' }, clean: { type: 'number' } }, required: ['findings', 'entries_checked', 'clean'] }
const FIX_S = { type: 'object', properties: { applied: { type: 'array', items: { type: 'string' } }, declined: { type: 'array', items: { type: 'string' } }, registry_requests: { type: 'array', items: REGREQ } }, required: ['applied', 'declined', 'registry_requests'] }
const REG_S = { type: 'object', properties: { applied: { type: 'array', items: { type: 'string' } }, declined: { type: 'array', items: { type: 'string' } }, changed_entries: { type: 'array', items: { type: 'string' } }, affected_files: { type: 'array', items: { type: 'string' } }, pending_left: { type: 'number' }, validate_clean: { type: 'boolean' } }, required: ['applied', 'declined', 'changed_entries', 'affected_files', 'pending_left', 'validate_clean'] }

const norm = t => { const m = String(t || '').match(/([a-z0-9-]+)\.md/); return m ? m[1] : null }

// ---------- Phase 1: closers ----------
phase('Close')
const closers = await parallel(NEW.map(s => () => agent(`${COMMON}

TASK: CLOSE THE FINAL ADVISOR REVIEW of ${P(s)} and harvest its outbound asks. You are the design advisor (the stronger model) finishing what the authoring workflow left open.
1. Read ${SCR}/tail/review-open/${s}.json: the final review's verdict, items (each a defect + required fix) and registry_conflicts. These were NEVER applied (the workflow ended on the review). A later CD-GDD-ALIGN revision may have fixed some — check the current section text first.
2. Context as needed: ${SCR}/wf/${s}/rulings.md (binding rulings, incl. "## Checkpoint rulings"), ${SCR}/wf/${s}/brief.md (locked facts). Read GDD sections by heading range only.
3. Apply every item that still holds, editing ${P(s)} only. For registry_conflicts: if this GDD is NOT the entry's source, move the GDD text to the registry value; if it IS the source and the GDD's value is the deliberate, reviewed one, keep the GDD and add a registry_request (the registry is updated in a later serial step — never edit entities.yaml yourself). Skip an item only when it is already done or impossible without editing another GDD (then turn it into an outbound ask).
4. Harvest OUTBOUND ASKS: Grep ${P(s)} (Dependencies, Interactions, Cross-References, Open Questions, Edge Cases) for amendments this GDD needs in OTHER GDDs — phrases like "must repeat", "routed", "owed", "ask", "amend", "requires <system> to", "provisional contract", "refresh". For each, return {target: "design/gdd/<slug>.md", ask: exact change wanted (quote the wording/values the target should state), source_location: "${P(s)} <section/line>"}. Only asks aimed at one of these existing GDDs: ${ALL.map(P).join(', ')}. Skip asks aimed at systems with no GDD yet (Vertical Slice etc.).
5. Grep the GDD for "[To be designed]" — must be zero.
Return the schema (applied: item -> what changed; skipped: item -> why).`, { ...OPUS, phase: 'Close', schema: CLOSE_S, label: `close:${s}` })))

const closeRes = {}
NEW.forEach((s, i) => { closeRes[s] = closers[i] })
const closeFailed = NEW.filter(s => !closeRes[s])
if (closeFailed.length) log(`closers failed (left unapplied): ${closeFailed.join(', ')}`)
let regQueue = []
let inbound = {}
for (const s of NEW) {
  const c = closeRes[s]; if (!c) continue
  regQueue.push(...c.registry_requests.map(r => ({ ...r, from: P(s) })))
  for (const a of c.outbound_asks) { const t = norm(a.target); if (!t || !ALL.includes(t) || t === s) continue; (inbound[t] = inbound[t] || []).push(a) }
}
log(`closers: ${NEW.length - closeFailed.length}/22; registry requests ${regQueue.length}; outbound asks ${Object.values(inbound).flat().length} to ${Object.keys(inbound).length} GDDs`)

// ---------- registry pass helper ----------
async function registryPass(label, reqs, extraFindings) {
  return agent(`${COMMON}

TASK: SERIAL REGISTRY PASS (${label}) on design/registry/entities.yaml — you are the only writer. Read its header comment for layout first; find entries with Grep "  - name: <name>" and Read by range.
A. Requests (apply each that is justified; decline with reason otherwise): ${JSON.stringify(reqs)}
B. Scanner findings for the registry (STALE_REGISTRY = the source GDD now states a different value: update the registry value to the source GDD's after confirming the quoted source text; UNLISTED_REF = a GDD reads the fact but is not in referenced_by: append it; LISTED_UNUSED = a GDD is in referenced_by but no longer mentions the entry: remove it from referenced_by unless it uses the fact under another name): ${JSON.stringify(extraFindings)}
Rules: on a value change set revised: ${DATE} and add "    # was: <old> before ${DATE} (consistency pass)". Never delete entries (status: deprecated if dead). Never create duplicates. referenced_by paths must exist on disk.
C. Un-park: for every "# pending referenced_by (GDD not yet written): <paths>" comment, move each path that now exists on disk into referenced_by (keep the rest; delete the comment when empty). Count comments left.
D. Run: cd /d/the-synaptic-sea-2d && bash .claude/scripts/registry.sh validate — fix every row you caused; re-run until clean; print the final counts.
Return: applied, declined, changed_entries (names whose value/expression changed), affected_files (every GDD path in referenced_by or source of a changed entry), pending_left, validate_clean.`, { ...OPUS, phase: 'Registry', schema: REG_S, label: `registry:${label}` })
}

phase('Registry')
const reg0 = await registryPass('closers', regQueue, [])
let regAffected = reg0 ? reg0.affected_files.map(norm).filter(Boolean) : []
if (!reg0) log('registry pass after closers FAILED')

// ---------- scan/fix rounds ----------
const scanPrompt = (s, round) => `${COMMON}

TASK: CONSISTENCY SCAN (round ${round}) of ${P(s)} against the registry. Observations with evidence only; you edit nothing except the hits file you generate.
1. Regenerate the hit list: cd /d/the-synaptic-sea-2d && python -I ${SCR}/tail/reg_hits.py ${s}  → ${SCR}/tail/hits/${s}.md (large: Grep its "^## " headings and Read in ranges). For every registry entry it lists: role OWNER (this GDD is source), LISTED (in referenced_by), MENTIONS-UNLISTED; the registry yaml; and GDD lines containing the exact name.
2. For each entry, compare the GDD's stated value/expression/variables/range/unit near those lines (Read the surrounding lines when needed) with the registry. Report only real, quoted disagreements:
 - CONFLICT: GDD (not the source) states a different value than the registry → fix = the exact replacement text in the GDD.
 - STALE_REGISTRY: this GDD IS the source and its current text differs from the registry → fix = the registry value to set.
 - NAME_MISSING: OWNER entry whose exact name never occurs in the GDD → fix = where to add "(registry: \`<name>\`)" next to the fact's definition (give the section/line).
 - UNLISTED_REF: GDD actually reads/uses the fact (not just a passing mention) but is not in referenced_by.
 - LISTED_UNUSED: GDD in referenced_by but has zero hits and does not use the fact under another name.
 Also check the GDD for statements about another system's owned value that contradict that owner (a value given in a dependency row/interaction table) when the value is registered.
 Do NOT report: wording differences with the same meaning, rounding shown as an example, values explicitly marked as examples, or a VS-tier alternative clearly labelled.
3. For each finding give location as "${P(s)}:L<line>" (or the registry line), registry_value and gdd_value as quoted text, target_file = the file that must change (the GDD path, or "design/registry/entities.yaml" for STALE_REGISTRY/UNLISTED_REF/LISTED_UNUSED).
Return the schema; entries_checked = number of entries in the hits file; clean = entries with no finding.`

const fixPrompt = (t, items, asks) => `${COMMON}

TASK: FIX ${P(t)} (you are the only writer of this file in this step).
A. Consistency findings to resolve (registry wins unless this GDD is the entry's source; in that case keep the GDD and add a registry_request): ${JSON.stringify(items)}
B. Inbound asks routed from other GDDs (judge each): ${JSON.stringify(asks)}
 Apply an ask when it states a contract, value, hook/mutator name, event or wording that this GDD should carry and it does not contradict a locked registry value, this GDD's own rulings (${SCR}/wf/${t}/rulings.md if present) or a user decision recorded in the GDD. Put it where the GDD's structure says it belongs (Interactions row, Dependencies row, a rule, an edge case, a tuning knob, an acceptance criterion) and keep it bidirectional with the asking GDD's wording. Decline when it contradicts (say exactly what), when it asks this GDD to own something another system owns, or when it is a design choice that needs the user — then add it to this GDD's Open Questions table with owner "user" or the asking GDD, target "next consistency pass", and report it as declined.
C. NAME_MISSING items: add "(registry: \`<name>\`)" at the fact's definition.
Return applied (finding/ask -> what changed), declined (-> why), registry_requests (only when this GDD is the source and the registry must follow it, or a referenced_by change is needed).`

const conflictsLog = []
let scope = ALL.slice()
let round = 1
const MAXFIX = 3
for (;;) {
  phase('Scan')
  const scans = await parallel(scope.map(s => () => agent(scanPrompt(s, round), { ...SON, phase: 'Scan', schema: FIND_S, label: `scan-r${round}:${s}` })))
  const scanFailed = scope.filter((s, i) => !scans[i])
  const findings = scans.filter(Boolean).flatMap(x => x.findings)
  const asksNow = round === 1 ? inbound : {}
  const nAsks = Object.values(asksNow).flat().length
  log(`round ${round}: scanned ${scope.length - scanFailed.length}/${scope.length}${scanFailed.length ? ' (failed: ' + scanFailed.join(', ') + ')' : ''}; findings ${findings.length} (${['CONFLICT','STALE_REGISTRY','NAME_MISSING','UNLISTED_REF','LISTED_UNUSED'].map(k => k + ' ' + findings.filter(f => f.kind === k).length).join(', ')}); inbound asks ${nAsks}`)
  conflictsLog.push(...findings.filter(f => f.kind === 'CONFLICT' || f.kind === 'STALE_REGISTRY').map(f => ({ ...f, round })))
  if (!findings.length && !nAsks) { log(`round ${round}: confirming scan CLEAN`); break }
  if (round > MAXFIX) { log(`round ${round}: ${findings.length} findings left after ${MAXFIX} fix rounds — reported, not fixed`); break }

  const gddFix = {}, regFind = []
  for (const f of findings) {
    const t = f.target_file.includes('entities.yaml') ? null : norm(f.target_file)
    if (t && ALL.includes(t)) (gddFix[t] = gddFix[t] || []).push(f); else regFind.push(f)
  }
  const targets = Array.from(new Set(Object.keys(gddFix).concat(Object.keys(asksNow))))
  phase('Fix')
  const fixes = await parallel(targets.map(t => () => agent(fixPrompt(t, gddFix[t] || [], asksNow[t] || []), { ...OPUS, phase: 'Fix', schema: FIX_S, label: `fix-r${round}:${t}` })))
  const fixReq = fixes.filter(Boolean).flatMap((x, i) => x.registry_requests.map(r => ({ ...r, from: P(targets[i]) })))
  targets.forEach((t, i) => { if (!fixes[i]) log(`fixer failed: ${t}`) })
  phase('Registry')
  const rg = await registryPass('round ' + round, fixReq, regFind)
  const affected = rg ? rg.affected_files.map(norm).filter(Boolean) : []
  scope = Array.from(new Set(targets.concat(affected).concat(regFind.map(f => norm(f.location)).filter(Boolean)))).filter(s => ALL.includes(s))
  if (round === 1) scope = Array.from(new Set(scope.concat(regAffected)))
  if (!scope.length) scope = ALL.slice()
  round++
}

// ---------- log ----------
phase('Log')
let logged = null
if (conflictsLog.length) {
  logged = await agent(`${COMMON}

TASK: Append to docs/consistency-failures.md (create it with the header block from .claude/skills is not needed — if absent, create it with: "# Consistency Failure Log", the two HTML comments "<!-- Auto-maintained by /consistency-check. Do not edit manually. -->" and "<!-- One entry per detected conflict, in chronological order. -->", and a table header "| Date | GDD A | GDD B | Conflict Type | Status |"). Read only its tail if it exists. For each conflict below append one table row AND one entry block:
### ${DATE} — /consistency-check (MVP GDD tail) — 🔴 CONFLICT
**Domain**: ... **Documents involved**: <source GDD> vs <conflicting GDD> **What happened**: ... **Resolution**: fixed in round N / registry updated / unresolved **Pattern**: generalised lesson.
Group near-identical conflicts (same entry, same cause) into one entry listing all documents. Conflicts: ${JSON.stringify(conflictsLog)}
Return a one-line count summary.`, { model: 'sonnet', effort: 'medium', phase: 'Log', label: 'log' })
}

return {
  date: DATE,
  closers: NEW.map(s => ({ s, applied: closeRes[s] ? closeRes[s].applied.length : null, skipped: closeRes[s] ? closeRes[s].skipped : null })),
  inbound_asks: Object.fromEntries(Object.entries(inbound).map(([k, v]) => [k, v.length])),
  registry0: reg0 && { applied: reg0.applied.length, declined: reg0.declined, pending_left: reg0.pending_left, clean: reg0.validate_clean },
  rounds: round,
  conflicts_logged: conflictsLog.length,
  log: logged,
}

