const FIX_S = { type: 'object', properties: { applied: { type: 'array', items: { type: 'string' } }, declined: { type: 'array', items: { type: 'string' } }, registry_requests: { type: 'array', items: REGREQ } }, required: ['applied', 'declined', 'registry_requests'] }
const DEC_S = { type: 'object', properties: { edits_file: { type: 'string' }, edits: { type: 'number' }, declined: { type: 'array', items: { type: 'string' } } }, required: ['edits_file', 'edits', 'declined'] }
const APPLY_S = { type: 'object', properties: { ok: { type: 'number' }, skipped: { type: 'array', items: { type: 'string' } }, validate_clean: { type: 'boolean' }, changed_entries: { type: 'array', items: { type: 'string' } }, affected_files: { type: 'array', items: { type: 'string' } } }, required: ['ok', 'skipped', 'validate_clean', 'changed_entries', 'affected_files'] }

const scanPrompt = (s, round) => `${COMMON}

TASK: CONSISTENCY SCAN (confirm round ${round}) of ${P(s)}. Observations with evidence only; edit nothing.
1. cd /d/the-synaptic-sea-2d && python -I ${T}/reg_hits.py ${s}  → ${T}/hits/${s}.md (large; Grep "^## " and Read in ranges). It lists every registry entry this GDD owns (OWNER), is listed for (LISTED), or names without being listed (MENTIONS-UNLISTED), with the registry yaml and the GDD lines naming it.
2. Compare each against the GDD text (Read surrounding lines when needed). Report only real, quoted disagreements:
 CONFLICT (non-source GDD states a different value/expression/range/unit → fix = exact replacement text in the GDD); STALE_REGISTRY (this GDD is the source and differs from the registry → fix = registry value to set); NAME_MISSING (OWNER entry whose exact name never occurs in the GDD → fix = where to add "(registry: \`<name>\`)"); UNLISTED_REF (GDD genuinely uses the fact, not listed); LISTED_UNUSED (listed but no use under any name).
 Not findings: same meaning in different words, labelled examples, clearly labelled VS-tier alternatives, "# consumer hints" comments.
3. location "${P(s)}:L<n>"; registry_value/gdd_value quoted; target_file = the GDD path or "design/registry/entities.yaml" (STALE_REGISTRY/UNLISTED_REF/LISTED_UNUSED).
Return the schema.`

const fixPrompt = (t, items) => `${COMMON}

TASK: FIX ${P(t)} (sole writer of this file in this step). Findings: ${JSON.stringify(items)}
Registry wins unless this GDD is the entry's source — then keep the GDD and return a registry_request. NAME_MISSING: add "(registry: \`<name>\`)" at the fact's definition. Decline (with reason) a finding that is wrong on inspection.
Return applied, declined, registry_requests.`

const decidePrompt = (round, i, items) => `${COMMON}

TASK: REGISTRY DECISIONS (round ${round}, batch ${i}) — read-only on the registry and GDDs; write ONE file: ${T}/regedits/r${round}-b${i}.json.
Items: ${JSON.stringify(items)}
Kinds: STALE_REGISTRY (verify the source GDD's text, set the registry to it); UNLISTED_REF (verify real use by Grep, add to referenced_by); LISTED_UNUSED (verify no use under the name or obvious aliases, remove from referenced_by); request items from GDD fixers (verify against the GDD text; may add a NEW entry — insert it by an edit on the preceding sibling entry's last line from the same source, full entry layout: name, status, source, referenced_by, attributes, added/revised ${DATE}).
For each accepted change write an edit {name: entry name, old_text: exact contiguous substring of THAT entry's current block (whole lines, unique in the block), new_text, reason}. Value changes: also set revised: ${DATE} and add "    # was: <old> before ${DATE} (consistency pass)". Keep referenced_by a valid block list ("referenced_by: []" when empty); paths must exist. Never delete entries. Merge items for the same entry into non-overlapping edits. Write {"edits":[...]} as UTF-8 JSON to the file (use python json.dump, ensure_ascii=False).
Return edits_file, edits (count), declined (item -> reason).`

const applyPrompt = (round) => `TASK: apply registry edits (round ${round}). Run exactly: cd /d/the-synaptic-sea-2d && cp design/registry/entities.yaml ${T}/entities.pre-r${round}.yaml && PYTHONIOENCODING=utf-8 python -I ${T}/apply_reg.py "${T}/regedits/r${round}-b*.json" && bash .claude/scripts/registry.sh validate
Report: ok = the "ok" count printed; skipped = each SKIP/NOENTRY line; validate_clean = all validate counts 0. If validate shows a DUPLICATE/LAYOUT/PATH_MISSING/STATUS problem, fix it in entities.yaml with the Edit tool (Grep the entry, Read its range) and re-run validate until clean. For each SKIP line, open the entry and apply the intended change by hand if it is still needed (the edit in ${T}/regedits/r${round}-b*.json shows the intent), else note why not. changed_entries = names of entries whose value/expression changed or were added; affected_files = every GDD path in source/referenced_by of those entries (Grep the blocks).`

const conflictsLog = []
let scope = ALL.slice()
let round = 2
for (;;) {
  phase('Scan')
  const scans = await parallel(scope.map(s => () => agent(scanPrompt(s, round), { model: 'sonnet', effort: 'high', phase: 'Scan', schema: FIND_S, label: `scan-r${round}:${s}` })))
  const failed = scope.filter((s, i) => !scans[i])
  const findings = scans.filter(Boolean).flatMap(x => x.findings)
  log(`round ${round}: scanned ${scope.length - failed.length}/${scope.length}${failed.length ? ' failed: ' + failed.join(', ') : ''}; findings ${findings.length} (${['CONFLICT','STALE_REGISTRY','NAME_MISSING','UNLISTED_REF','LISTED_UNUSED'].map(k => k + ' ' + findings.filter(f => f.kind === k).length).join(', ')})`)
  conflictsLog.push(...findings.filter(f => f.kind === 'CONFLICT' || f.kind === 'STALE_REGISTRY').map(f => ({ ...f, round })))
  if (!findings.length && !failed.length) { log(`round ${round}: CONFIRMING SCAN CLEAN over ${scope.length} GDDs`); break }
  if (round >= 4) { log(`round ${round}: ${findings.length} findings left after the fix-round cap — reported, not fixed`); break }

  const gddFix = {}, regItems = []
  for (const f of findings) {
    const t = f.target_file.includes('entities.yaml') ? null : norm(f.target_file)
    if (t && ALL.includes(t)) (gddFix[t] = gddFix[t] || []).push(f); else regItems.push(f)
  }
  const targets = Object.keys(gddFix)
  phase('Fix')
  const fixes = await parallel(targets.map(t => () => agent(fixPrompt(t, gddFix[t]), { model: 'opus', phase: 'Fix', schema: FIX_S, label: `fix-r${round}:${t}` })))
  targets.forEach((t, i) => { if (!fixes[i]) log(`fixer failed: ${t}`) })
  const reqs = fixes.flatMap((x, i) => x ? x.registry_requests.map(r => ({ ...r, kind: 'request', from: P(targets[i]) })) : [])
  const all = regItems.concat(reqs)
  let affected = []
  if (all.length) {
    phase('Registry')
    const byName = {}
    for (const it of all) (byName[it.name] = byName[it.name] || []).push(it)
    const names = Object.keys(byName).sort()
    const batches = []; let cur = []
    for (const n of names) { cur = cur.concat(byName[n]); if (cur.length >= 40) { batches.push(cur); cur = [] } }
    if (cur.length) batches.push(cur)
    const dec = await parallel(batches.map((b, i) => () => agent(decidePrompt(round, i, b), { model: 'opus', phase: 'Registry', schema: DEC_S, label: `decide-r${round}:b${i}` })))
    dec.forEach((d, i) => { if (!d) log(`decide batch ${i} failed`) })
    const ap = await agent(applyPrompt(round), { model: 'sonnet', effort: 'high', phase: 'Registry', schema: APPLY_S, label: `apply-r${round}` })
    log(`round ${round} registry: ${batches.length} batches, applied ${ap ? ap.ok : 'FAILED'}, skipped ${ap ? ap.skipped.length : '?'}, validate ${ap ? ap.validate_clean : '?'}`)
    affected = ap ? ap.affected_files.map(norm).filter(Boolean) : []
  }
  scope = Array.from(new Set(targets.concat(affected).concat(failed))).filter(s => ALL.includes(s))
  if (!scope.length) scope = ALL.slice()
  round++
}

phase('Log')
const logRes = await agent(`${COMMON}

TASK: append to docs/consistency-failures.md (Read only its tail if it exists; if absent create it with "# Consistency Failure Log", the two comments "<!-- Auto-maintained by /consistency-check. Do not edit manually. -->" and "<!-- One entry per detected conflict, in chronological order. -->", then the table header "| Date | GDD A | GDD B | Conflict Type | Status |" and its separator row).
Inputs: round-1 conflicts (all resolved in round 1 by GDD fixers and the registry pass) in ${T}/conflicts-round1.json (212 items; read it with python, it is large), and later-round conflicts: ${JSON.stringify(conflictsLog)}.
Group by entry name + cause (do not write 212 separate blocks): one table row and one block per group:
### ${DATE} — /consistency-check (MVP GDD tail) — 🔴 CONFLICT
**Domain**: ... **Documents involved**: <source GDD> vs <other GDDs> **What happened**: entry, values **Resolution**: fixed round N (GDD text moved to registry value / registry updated to source) or Unresolved **Pattern**: the generalised lesson.
Close with a short "Patterns across this pass" paragraph (e.g. authors citing an owner's provisional value before the owner GDD existed). Use a python script for generation; print counts. Return a one-line summary.`, { model: 'opus', phase: 'Log', label: 'log' })

return { final_round: round, later_conflicts: conflictsLog.length, log: logRes }

