export const meta = {
  name: 'mvp-gdd-close-r4',
  description: 'Close the 104 round-4 consistency findings: fix GDDs, decide+apply registry edits, verify each finding closed, regression-check changed entries, correct the conflict log',
  phases: [
    { title: 'Fix', detail: 'per-target GDD fixer (Opus) seeded from findings-r4.json' },
    { title: 'Registry', detail: 'Opus decide batches -> scripted apply + validate' },
    { title: 'Verify', detail: 'per-finding closed/open check + regression on changed entries (Sonnet high)' },
    { title: 'Log', detail: 'correct docs/consistency-failures.md statuses' },
  ],
}
const DATE = '2026-10-27'
const ROOT = 'D:/the-synaptic-sea-2d'
const T = 'C:/Users/dasbl/AppData/Local/Temp/claude/D--the-synaptic-sea-2d/e887ccb9-1186-40d9-9566-5eacccbd9b44/scratchpad/tail'
const ALL = ['command-simulation-layer','pixel-perfect-render-pipeline-camera','player-controller-input','life-support-graph','save-load-and-versioned-format','item-and-module-database','emitter-state-and-light-exposure-query','failure-and-trail-system','2d-lighting-and-occlusion','interaction-system','suit-and-equipment','ship-section-and-layout-data-model','ship-body-and-interior-physics','derelict-authoring-handmade-kits','attention-system','modular-ship-assembly','web-map-and-transit','horror-entities','sanity-and-hallucination-rules','boarding-and-salvage','perception-filter','chart-table-web-map-and-menus','adaptive-audio-and-tells','hud-and-suit-layer','in-world-instruments-and-inspect-view','debug-overlay-true-values']
const P = s => `design/gdd/${s}.md`
const norm = t => { const m = String(t || '').match(/([a-z0-9-]+)\.md/); return m ? m[1] : null }
const COMMON = `PROJECT: The Synaptic Sea (Godot 4.7.2, 2D co-op survival horror). Repo ${ROOT} (Bash: cd /d/the-synaptic-sea-2d). Autonomous mode: no questions; decide by these rules and report decisions.
CONTEXT: 26 system GDDs in design/gdd/ (150-370 KB each). design/registry/entities.yaml (~830 entries) is the cross-GDD source of truth: an entry's source: GDD owns its value; consumers conform to it (TIE-BREAK: the source GDD always wins; never move the registry toward a consumer GDD). referenced_by lists GDDs that read it; "# consumer hints" comments are informal. This is the close pass for findings the last confirming scan raised.
READ RULES: a hook refuses whole-file Read over 40 KB: Grep (-n, context) and Read by offset/limit only.
WRITE RULES: edit only what the task names. Never edit systems-index.md, production/session-state/*, git; never commit. Keep heading sets/order. Amendments to the four pre-workflow GDDs (command-simulation-layer, pixel-perfect-render-pipeline-camera, player-controller-input, life-support-graph) carry "*(Amended ${DATE} — consistency pass, routed from <gdd>)*". Precise edits, never rewrites. Also fix the SAME stale value elsewhere in the same file when you see it (Grep the name), so a later scan does not re-find it.`
const FIND = { type: 'object', properties: { kind: { type: 'string' }, name: { type: 'string' }, target_file: { type: 'string' }, location: { type: 'string' }, registry_value: { type: 'string' }, gdd_value: { type: 'string' }, fix: { type: 'string' } }, required: ['kind', 'name', 'target_file', 'location', 'registry_value', 'gdd_value', 'fix'] }
const REGREQ = { type: 'object', properties: { name: { type: 'string' }, change: { type: 'string' }, reason: { type: 'string' } }, required: ['name', 'change', 'reason'] }
const FIX_S = { type: 'object', properties: { applied: { type: 'array', items: { type: 'string' } }, declined: { type: 'array', items: { type: 'string' } }, registry_requests: { type: 'array', items: REGREQ } }, required: ['applied', 'declined', 'registry_requests'] }
const DEC_S = { type: 'object', properties: { edits_file: { type: 'string' }, edits: { type: 'number' }, declined: { type: 'array', items: { type: 'string' } } }, required: ['edits_file', 'edits', 'declined'] }
const APPLY_S = { type: 'object', properties: { ok: { type: 'number' }, skipped: { type: 'array', items: { type: 'string' } }, validate_clean: { type: 'boolean' }, changed_entries: { type: 'array', items: { type: 'string' } }, affected_files: { type: 'array', items: { type: 'string' } } }, required: ['ok', 'skipped', 'validate_clean', 'changed_entries', 'affected_files'] }
const VER_S = { type: 'object', properties: { results: { type: 'array', items: { type: 'object', properties: { idx: { type: 'number' }, status: { type: 'string', enum: ['closed', 'open', 'invalid'] }, evidence: { type: 'string' } }, required: ['idx', 'status', 'evidence'] } }, regressions: { type: 'array', items: FIND } }, required: ['results', 'regressions'] }

const r4 = args.findings
log(`seeded ${r4.length} round-4 findings`)
const gddFix = {}, regItems = []
for (const f of r4) {
  const t = f.target_file.includes('entities.yaml') ? null : norm(f.target_file)
  if (t && ALL.includes(t)) (gddFix[t] = gddFix[t] || []).push(f); else regItems.push(f)
}
const targets = Object.keys(gddFix)
phase('Fix')
const fixes = await parallel(targets.map(t => () => agent(`${COMMON}

TASK: FIX ${P(t)} (sole writer of this file in this step). Findings: ${JSON.stringify(gddFix[t])}
Registry wins unless this GDD is the entry's source — then keep the GDD and return a registry_request. Decline (with reason) a finding that is wrong on inspection.
Return applied, declined, registry_requests.`, { model: 'opus', phase: 'Fix', schema: FIX_S, label: `fix-r5:${t}` })))
targets.forEach((t, i) => { if (!fixes[i]) log(`fixer failed: ${t}`) })
const reqs = fixes.flatMap((x, i) => x ? x.registry_requests.map(r => ({ ...r, kind: 'request', from: P(targets[i]) })) : [])
const all = regItems.concat(reqs)
let ap = null
if (all.length) {
  phase('Registry')
  const byName = {}
  for (const it of all) (byName[it.name] = byName[it.name] || []).push(it)
  const names = Object.keys(byName).sort()
  const batches = []; let cur = []
  for (const n of names) { cur = cur.concat(byName[n]); if (cur.length >= 25) { batches.push(cur); cur = [] } }
  if (cur.length) batches.push(cur)
  const dec = await parallel(batches.map((b, i) => () => agent(`${COMMON}

TASK: REGISTRY DECISIONS (round 5, batch ${i}) — read-only on the registry and GDDs; write ONE file: ${T}/regedits/r5-b${i}.json.
Items: ${JSON.stringify(b)}
Kinds: STALE_REGISTRY (verify the source GDD's text, set the registry to it); UNLISTED_REF (verify real use by Grep, add to referenced_by); LISTED_UNUSED (verify no use under the name or obvious aliases, remove from referenced_by); request items from GDD fixers (verify against the GDD text; a request from a NON-source GDD to change a value is declined — consumers conform; may add a NEW entry — insert it by an edit on the preceding sibling entry's last line from the same source, full entry layout: name, status, source, referenced_by, attributes, added/revised ${DATE}).
For each accepted change write an edit {name, old_text: exact contiguous substring of THAT entry's current block (whole lines, unique in the block), new_text, reason}. Value changes: also set revised: ${DATE} and add "    # was: <old> before ${DATE} (consistency pass)". Keep referenced_by a valid block list ("referenced_by: []" when empty); paths must exist. Never delete entries. Merge items for the same entry into non-overlapping edits. Write {"edits":[...]} as UTF-8 JSON (python json.dump, ensure_ascii=False).
Return edits_file, edits (count), declined (item -> reason).`, { model: 'opus', phase: 'Registry', schema: DEC_S, label: `decide-r5:b${i}` })))
  dec.forEach((d, i) => { if (!d) log(`decide batch ${i} failed`) })
  ap = await agent(`TASK: apply registry edits (round 5). Run exactly: cd /d/the-synaptic-sea-2d && cp design/registry/entities.yaml ${T}/entities.pre-r5.yaml && PYTHONIOENCODING=utf-8 python -I ${T}/apply_reg.py "${T}/regedits/r5-b*.json" && bash .claude/scripts/registry.sh validate
Report: ok = the "ok" count printed; skipped = each SKIP/NOENTRY line; validate_clean = all validate counts 0. If validate shows a problem, fix it in entities.yaml with the Edit tool (Grep the entry, Read its range) and re-run validate until clean. For each SKIP line, open the entry and apply the intended change by hand if still needed (the edit JSON shows the intent), else note why not. changed_entries = names of entries whose value/expression/referenced_by changed or were added; affected_files = every GDD path in source/referenced_by of those entries.`, { model: 'sonnet', effort: 'high', phase: 'Registry', schema: APPLY_S, label: 'apply-r5' })
  log(`registry: ${batches.length} batches, applied ${ap ? ap.ok : 'FAILED'}, skipped ${ap ? ap.skipped.length : '?'}, validate ${ap ? ap.validate_clean : '?'}`)
}

phase('Verify')
const changed = ap ? ap.changed_entries : []
const byGdd = {}
r4.forEach((f, idx) => { const g = norm(f.location) || norm(f.target_file) || 'registry'; (byGdd[g] = byGdd[g] || []).push({ idx, ...f }) })
for (const a of (ap ? ap.affected_files.map(norm).filter(Boolean) : [])) if (!byGdd[a] && ALL.includes(a)) byGdd[a] = []
const vg = Object.keys(byGdd)
const ver = await parallel(vg.map(g => () => agent(`${COMMON}

TASK: VERIFY (read-only; edit nothing). GDD ${g === 'registry' ? '(registry-only items)' : P(g)}.
A. For each item below decide whether it is now CLOSED against the CURRENT files: the GDD text and the registry entry agree (CONFLICT/STALE_REGISTRY), the GDD is listed in referenced_by (UNLISTED_REF), or it is no longer listed (LISTED_UNUSED) — or the fixer/decider declined it for a sound reason you can confirm (then "invalid"). Check by Grep of the name in the GDD and in design/registry/entities.yaml (Read the entry block). Quote the deciding text as evidence. Items: ${JSON.stringify(byGdd[g])}
B. Regression: ${g === 'registry' ? 'skip.' : `for each of these registry entries changed in this pass that ${P(g)} names: ${JSON.stringify(changed)} — Grep the name in the GDD and compare its stated value/expression/range with the current registry entry; report real, quoted disagreements as regressions (FIND schema; kind CONFLICT, target_file the GDD, fix = replacement text). Same-meaning wording is not a finding.`}
Return results (one per item, by idx) and regressions.`, { model: 'sonnet', effort: 'high', phase: 'Verify', schema: VER_S, label: `verify:${g}` })))
const results = ver.filter(Boolean).flatMap(v => v.results)
const regressions = ver.filter(Boolean).flatMap(v => v.regressions)
vg.forEach((g, i) => { if (!ver[i]) log(`verify failed: ${g}`) })
const open = results.filter(r => r.status === 'open').map(r => ({ ...r4[r.idx], evidence: r.evidence }))
log(`verify: closed ${results.filter(r => r.status === 'closed').length}, invalid ${results.filter(r => r.status === 'invalid').length}, open ${open.length}, unchecked ${r4.length - results.length}; regressions ${regressions.length}`)

// one targeted repair for anything still open or regressed in GDDs
const rep = {}
for (const f of open.concat(regressions)) { const t = f.target_file.includes('entities.yaml') ? null : norm(f.target_file); if (t && ALL.includes(t)) (rep[t] = rep[t] || []).push(f) }
const regOpen = open.filter(f => f.target_file.includes('entities.yaml'))
const repT = Object.keys(rep)
let repaired = []
if (repT.length) {
  phase('Fix')
  const rf = await parallel(repT.map(t => () => agent(`${COMMON}

TASK: REPAIR ${P(t)} — these items were verified still OPEN (or are regressions) after the close pass. Make the GDD text agree with the current registry entry (source wins; if this GDD IS the source, return a registry_request instead). Items: ${JSON.stringify(rep[t])}
Return applied, declined, registry_requests.`, { model: 'opus', phase: 'Fix', schema: FIX_S, label: `repair:${t}` })))
  repaired = rf.map((x, i) => ({ gdd: repT[i], ...(x || { failed: true }) }))
}

const summary = { seeded: r4.length, verify: results.map(r => ({ idx: r.idx, name: r4[r.idx] && r4[r.idx].name, kind: r4[r.idx] && r4[r.idx].kind, status: r.status, evidence: r.evidence })), regressions, open, regOpen, repaired, apply: ap }
phase('Log')
const logRes = await agent(`${COMMON}

TASK: correct docs/consistency-failures.md (auto-maintained by /consistency-check; scripted edits with python, preserve the file's line endings). Do NOT read it whole; Grep/Read ranges.
The previous writer marked 36 groups "Unresolved" with the reason "round-4 edits were not yet in the GDDs when logged". That reason is wrong: round-4 findings were never edited because the script stopped at its fix-round cap. They have now been handled by a close pass (round 5). Close-pass outcome per round-4 finding (status closed/invalid/open; "open" items then went to one repair agent — repaired: ${JSON.stringify(repaired.map(r => ({ gdd: r.gdd, applied: r.applied, declined: r.declined })))}): ${JSON.stringify(summary.verify)}
For each Unresolved group (table row AND matching ### block): if its findings are closed/invalid or were repaired, set Status/Resolution to "Resolved — round-5 close pass (${DATE})" (invalid: "Not a conflict on inspection — round-5 close pass"); otherwise keep Unresolved with a correct reason. Remove the wrong "not yet in the GDDs" wording everywhere.
Then sanity-check: count table rows starting "| 2026" vs "### 2026" blocks; table rows must be contiguous under the header. Print the counts before/after. Return a one-line summary with the counts and how many groups remain Unresolved.`, { model: 'opus', phase: 'Log', label: 'log-fix' })

return { summary: { seeded: r4.length, closed: results.filter(r => r.status === 'closed').length, invalid: results.filter(r => r.status === 'invalid').length, open: open.length, unchecked: r4.length - results.length, regressions: regressions.length, regOpen: regOpen.length, repaired: repaired.map(r => ({ gdd: r.gdd, applied: (r.applied || []).length, declined: r.declined || [], reqs: r.registry_requests || [] })) }, apply: ap ? { ok: ap.ok, skipped: ap.skipped, validate_clean: ap.validate_clean } : null, log: logRes }

