export const meta = {
  name: 'design-review-all-mvp',
  description: 'Full /design-review of all 26 MVP GDDs: main review, specialist panel, creative-director verdict; fix NEEDS REVISION and re-review once; write review logs',
  phases: [
    { title: 'Review', detail: 'main review (Sonnet) + specialists (Sonnet) + creative-director verdict (Opus)' },
    { title: 'Revise', detail: 'NEEDS REVISION: fixer (Sonnet high) then full lean re-review + CD verdict' },
    { title: 'Log', detail: 'review-log entry with hash receipt (Haiku)' },
  ],
}
const DATE = '2026-10-27'
const ALL = ['command-simulation-layer','pixel-perfect-render-pipeline-camera','player-controller-input','life-support-graph','save-load-and-versioned-format','item-and-module-database','emitter-state-and-light-exposure-query','failure-and-trail-system','2d-lighting-and-occlusion','interaction-system','suit-and-equipment','ship-section-and-layout-data-model','ship-body-and-interior-physics','derelict-authoring-handmade-kits','attention-system','modular-ship-assembly','web-map-and-transit','horror-entities','sanity-and-hallucination-rules','boarding-and-salvage','perception-filter','chart-table-web-map-and-menus','adaptive-audio-and-tells','hud-and-suit-layer','in-world-instruments-and-inspect-view','debug-overlay-true-values']
const P = s => `design/gdd/${s}.md`
const SPEC_TYPES = ['game-designer','systems-designer','qa-lead','economy-designer','ai-programmer','level-designer','ux-designer','ui-programmer','narrative-director','gameplay-programmer','network-programmer','audio-director','performance-analyst','godot-specialist']
const MAX_SPEC = 5

const CTX = `PROJECT: The Synaptic Sea — Godot 4.7.2 / GDScript, 2D HD-pixel-art co-op survival horror. Repo D:/the-synaptic-sea-2d (Bash: cd /d/the-synaptic-sea-2d). workflow tier: full (all 8 GDD sections REQUIRED). review_mode: full. automation: autonomous.
READ RULES: GDDs are 150-370 KB; a hook refuses whole-file Read over 40 KB. Grep "^#" (content mode, -n) for headings, then Read every section by offset/limit — read the WHOLE document this way, section by section; do not skip sections.
Cross-document facts: prefer design/registry/entities.yaml (an entry's source: GDD owns its value; referenced_by lists readers). Grep "source: design/gdd/<slug>.md" -A 6 for owned entries and "design/gdd/<slug>.md" -B 8 for referenced ones. Pillars/tone: design/gdd/game-concept.md (Grep headings, read the pillars section). User decisions in force: chest-mounted lamp, throwable glowsticks, lethal friendly fire, zoom in/out, MVP death = restart from last autosave.
The 26 GDDs were authored in an automated run and passed a registry consistency check today; this is their FIRST formal design review.`

const FINDING = { type: 'object', properties: { severity: { type: 'string', enum: ['BLOCKING', 'RECOMMENDED', 'NICE'] }, section: { type: 'string' }, finding: { type: 'string' }, fix: { type: 'string' } }, required: ['severity', 'section', 'finding', 'fix'] }
const MAIN_S = { type: 'object', properties: {
  freshness: { type: 'string' }, sections_present: { type: 'array', items: { type: 'string' } }, sections_missing: { type: 'array', items: { type: 'string' } },
  dependency_graph: { type: 'array', items: { type: 'object', properties: { system: { type: 'string' }, file: { type: 'string' }, exists: { type: 'boolean' } }, required: ['system', 'file', 'exists'] } },
  findings: { type: 'array', items: FINDING }, untestable_acs: { type: 'array', items: { type: 'string' } },
  domains: { type: 'array', items: { type: 'string', enum: SPEC_TYPES } }, scope_signal: { type: 'string', enum: ['S', 'M', 'L', 'XL'] }, summary: { type: 'string' } },
  required: ['freshness', 'sections_present', 'sections_missing', 'dependency_graph', 'findings', 'untestable_acs', 'domains', 'scope_signal', 'summary'] }
const SPEC_S = { type: 'object', properties: { findings: { type: 'array', items: FINDING }, disagreements_with_main: { type: 'array', items: { type: 'string' } } }, required: ['findings', 'disagreements_with_main'] }
const CD_S = { type: 'object', properties: {
  verdict: { type: 'string', enum: ['APPROVED', 'NEEDS REVISION', 'MAJOR REVISION NEEDED', 'NOT ASSESSED'] },
  required_before_implementation: { type: 'array', items: FINDING }, recommended: { type: 'array', items: FINDING }, nice_to_have: { type: 'array', items: { type: 'string' } },
  disagreements: { type: 'array', items: { type: 'string' } }, synthesis: { type: 'string' } },
  required: ['verdict', 'required_before_implementation', 'recommended', 'nice_to_have', 'disagreements', 'synthesis'] }
const FIX_S = { type: 'object', properties: {
  applied: { type: 'array', items: { type: 'string' } }, declined: { type: 'array', items: { type: 'string' } },
  user_decisions: { type: 'array', items: { type: 'string' } },
  registry_requests: { type: 'array', items: { type: 'object', properties: { name: { type: 'string' }, change: { type: 'string' }, reason: { type: 'string' } }, required: ['name', 'change', 'reason'] } },
  cross_gdd_notes: { type: 'array', items: { type: 'string' } } },
  required: ['applied', 'declined', 'user_decisions', 'registry_requests', 'cross_gdd_notes'] }

const mainPrompt = (s, re) => `${CTX}

TASK: /design-review ${re ? 'RE-REVIEW (lean: all phases, no specialists) after revision' : 'main review, phases 1-3'} of ${P(s)}. Read-only — edit nothing.
1. Freshness: bash .claude/scripts/review-receipts.sh check "design/gdd/reviews/${s}-review-log.md" "${P(s)}" "design/registry/entities.yaml" — report its output (expected RECEIPT: NONE${re ? ' or CHANGED' : ''}).
2. Completeness: bash .claude/scripts/gdd-structure-check.sh ${P(s)}. All 8 sections REQUIRED (Overview, Player Fantasy, Detailed Rules/Detailed Design, Formulas, Edge Cases, Dependencies, Tuning Knobs, Acceptance Criteria); spot-read any section a verdict turns on (an empty heading fails).
3. Dependency graph: for every system in Dependencies, Glob its GDD under design/gdd/ and report exists true/false.
4. Read the whole GDD section by section. Internal consistency (formulas vs described behaviour, edge cases vs rules, bidirectional dependencies), implementability (precise enough to implement without guessing, hand-waves, performance), cross-system consistency against the registry, pillars and tone. Quote every acceptance criterion that is not independently testable, with a measurable rewrite.
${re ? `5. This is a re-review. Prior blocking items and the fixer's report: ${JSON.stringify(re)}. Check each was actually resolved, AND review the whole document afresh (a section-scoped re-review misses defects).` : `5. domains: pick from the list the specialists this GDD needs per the design-review domain table (game-designer for any gameplay/player-facing rules; systems-designer for formulas/interaction rules; qa-lead for ACs; ux-designer/ui-programmer for UI/HUD; ai-programmer for AI/pathing; network-programmer for sync/replication; audio-director for audio; performance-analyst for perf budgets; godot-specialist for engine APIs; narrative-director for lore/story; level-designer for layout/spawning; economy-designer for costs/loot/progression; gameplay-programmer for feel/timing). Order by importance.`}
Findings: severity BLOCKING (must fix before implementation), RECOMMENDED, NICE; section; finding; concrete fix. Scope signal S/M/L/XL. Return the schema.`

const specPrompt = (s, type, main) => `${CTX}

You are the ${type} on a full /design-review of ${P(s)} (read-only — edit nothing). Here is the main review's structural findings so far: ${JSON.stringify({ findings: main.findings, untestable_acs: main.untestable_acs, sections_missing: main.sections_missing })}
Your job is NOT to validate this design — your job is to find problems. Challenge the design choices from your domain expertise. What is wrong, underspecified, likely to cause problems, or missing entirely? Be specific and critical; quote GDD lines (file:Lnn). Disagreement with the main review is welcome. Read the sections relevant to your domain in full (by offset/limit).
${type === 'game-designer' ? 'Anchor your review to the Player Fantasy section. Does this design deliver that fantasy? Flag rules that serve implementability but undermine the intended feeling.' : ''}${type === 'systems-designer' ? 'For every formula, plug in boundary values (min and max plausible inputs) and report any degenerate output — negative, division by zero, infinity, overflow, nonsensical results.' : ''}${type === 'qa-lead' ? 'Review every acceptance criterion; flag any not independently testable and give a concrete rewrite.' : ''}${['godot-specialist','gameplay-programmer','ui-programmer','ai-programmer','network-programmer'].includes(type) ? ' Godot 4.7.2 is after your training data: check docs/engine-reference/godot/ before judging an API claim; flag API claims you cannot verify as [UNV] rather than wrong.' : ''}
Severity: BLOCKING only for defects that would make implementation wrong or impossible. Return the schema.`

const cdPrompt = (s, main, specs, re) => `${CTX}

You are the creative-director, the SENIOR reviewer of the /design-review of ${P(s)} (read-only). ${re ? 'This is the RE-REVIEW after one revision pass.' : ''}
Main review: ${JSON.stringify(main)}
Specialist findings: ${JSON.stringify(specs)}
Synthesise these findings. What are the most important issues? Do you agree with the specialists? Spot-check the GDD sections the verdict turns on (Grep + Read by offset/limit). Verdict words (this skill's, never director-gate words): APPROVED (no blocking items remain), NEEDS REVISION (blocking items that targeted edits can fix), MAJOR REVISION NEEDED (the design itself is wrong — needs a rethink, not edits), NOT ASSESSED (the review could not be performed; say why).
Put only true blockers in required_before_implementation; list specialist disagreements (with each other or with you) explicitly in disagreements — do not silently resolve them. Every finding source-tagged in its text, e.g. "[systems-designer] ...". Return the schema.`

const fixPrompt = (s, cd) => `${CTX}

TASK: revise ${P(s)} to address the design-review findings (you are the only writer of this file now). Blocking: ${JSON.stringify(cd.required_before_implementation)}. Recommended: ${JSON.stringify(cd.recommended)}.
Rules: fix every BLOCKING item; apply RECOMMENDED items that are clear improvements and need no new creative direction. Precise edits with Edit (Grep the text, Read the range); never rewrite whole sections; keep the heading set and order. Mark each edited paragraph or row "*(Amended ${DATE} — design review)*". Keep the GDD consistent with itself: when you change a value, Grep the whole GDD for every other place it appears and update them all.
