Return "ok" and the hash lines.`

log(`Full review of ${ALL.length} GDDs; up to ${MAX_SPEC} specialists each (extra domains are logged, not run)`)

const results = await pipeline(ALL,
  // Stage 1: main review
  s => agent(mainPrompt(s, null), { model: 'sonnet', effort: 'high', phase: 'Review', schema: MAIN_S, label: `main:${s}` }),
  // Stage 2: specialists in parallel + CD verdict
  async (main, s) => {
    if (!main) return { s, failed: 'main review' }
    let types = main.domains.filter((t, i, a) => SPEC_TYPES.includes(t) && a.indexOf(t) === i)
    for (const base of ['qa-lead', 'systems-designer', 'game-designer']) if (!types.includes(base)) types.unshift(base)
    const dropped = types.slice(MAX_SPEC); types = types.slice(0, MAX_SPEC)
