}
const F = 'C:/Users/dasbl/AppData/Local/Temp/claude/D--the-synaptic-sea-2d/e887ccb9-1186-40d9-9566-5eacccbd9b44/scratchpad/tail/dr-reg-apply.json'
const S = {
  type: 'object',
  properties: {
    edits: { type: 'array', items: { type: 'object', properties: { idx: { type: 'integer' }, name: { type: 'string' }, old_text: { type: 'string' }, new_text: { type: 'string' } }, required: ['idx', 'name', 'old_text', 'new_text'] } },
    new_entries: { type: 'array', items: { type: 'object', properties: { idx: { type: 'integer' }, name: { type: 'string' }, section: { type: 'string', enum: ['entities', 'items', 'formulas', 'constants'] }, yaml: { type: 'string' } }, required: ['idx', 'name', 'section', 'yaml'] } },
    declined: { type: 'array', items: { type: 'object', properties: { idx: { type: 'integer' }, name: { type: 'string' }, why: { type: 'string' } }, required: ['idx', 'name', 'why'] } },
  },
  required: ['edits', 'new_entries', 'declined'],
}
const prompt = (lo, hi) => `You translate design-review registry requests into exact text edits for D:/the-synaptic-sea-2d/design/registry/entities.yaml. You are READ-ONLY: do not use Edit or Write on any file. Your structured output is applied by the parent.

Input: read ${F} (JSON array) and handle only the items whose idx is between ${lo} and ${hi} inclusive. Each item has name, change, reason, by (the requesting GDD slug; its file is design/gdd/<by>.md).

For each item:
1. Grep the registry for '^  - name: "?<name>"?$' and Read that entry (offset/limit; the file is large, do not read it whole).
2. Verify the request against the requesting GDD's CURRENT text (grep the GDD for the name). The registry must mirror the owner GDD. If the GDD does not state what the request says, or the request is only a no-op/comment, decline it with the reason.
3. Existing entry -> emit edits: old_text must be an exact substring of THAT entry (copy bytes exactly, LF line endings, 4/6-space indentation as in the file) occurring once within the entry; new_text is the replacement. Follow the registry rules: when a value/expression changes, set 'revised: 2026-10-27' and add a comment line '# was: <old> before 2026-10-27 (design review)' under the changed attribute. Never delete entries; never edit other entries. Keep referenced_by as a block list.
4. Missing entry -> emit new_entries with section (constants for scalar knobs, formulas for expressions, entities/items otherwise) and the full YAML block in the exact style of neighbouring entries in that section: '  - name: X' then 4-space keys status: active, source: design/gdd/<by>.md, referenced_by: (block list, or [] if none; add only GDDs that actually mention the name — grep design/gdd/*.md), attributes: (value/unit/range or expression/variables/output_range), added: 2026-10-27, and a '# ' note for provisional/pending-user-decision values. Only the requesting GDD may be source.
Every idx in your range must appear exactly once across edits/new_entries/declined (an item may need several edits; repeat its idx).`
const batches = []
for (let lo = 0; lo <= 265; lo += 12) batches.push([lo, Math.min(lo + 11, 265)])
const res = await parallel(batches.map(([lo, hi]) => () => agent(prompt(lo, hi), { model: 'sonnet', effort: 'medium', phase: 'Translate', schema: S, label: `reg:${lo}-${hi}` })))
const failed = batches.filter((b, i) => !res[i]).map(b => b.join('-'))
if (failed.length) log('batches without output: ' + failed.join(', '))
return { edits: res.filter(Boolean).flatMap(r => r.edits), new_entries: res.filter(Boolean).flatMap(r => r.new_entries), declined: res.filter(Boolean).flatMap(r => r.declined), failed }

