"""Quote unquoted scalar values that break strict YAML parsing, one failing line at a time."""
import yaml, re, sys
Y = 'D:/the-synaptic-sea-2d/design/registry/entities.yaml'
lines = open(Y, encoding='utf-8', newline='').read().split('\n')
fixed = 0
for it in range(800):
    try:
        yaml.safe_load('\n'.join(lines)); print('PARSES after', fixed, 'quotes'); break
    except yaml.YAMLError as e:
        ln = e.problem_mark.line
        done = False
        for k in range(ln, max(ln - 4, -1), -1):
            m = re.match(r'^(\s+(?:- )?[A-Za-z_][\w ]*?: )(.+)$', lines[k])
            if m and not m.group(2).startswith(('"', "'", '[', '{', '|', '>')):
                v = m.group(2).replace('\\', '\\\\').replace('"', '\\"')
                lines[k] = m.group(1) + '"' + v + '"'; fixed += 1; done = True; break
        if not done:
            print('cannot fix line', ln + 1, repr(lines[ln][:200]), str(e)[:200]); break
open(Y, 'w', encoding='utf-8', newline='').write('\n'.join(lines))

