${type === 'game-designer' ? 'Anchor your review to the Player Fantasy section. Does this design deliver that fantasy? Flag rules that serve implementability but undermine the intended feeling.' : ''}${type === 'systems-designer' ? 'For every formula, plug in boundary values (min and max plausible inputs) and report any degenerate output — negative, division by zero, infinity, overflow, nonsensical results.' : ''}${type === 'qa-lead' ? 'Review every acceptance criterion; flag any not independently testable and give a concrete rewrite.' : ''}${['godot-specialist','gameplay-programmer','ui-programmer','ai-programmer','network-programmer'].includes(type) ? ' Godot 4.7.2 is after your training data: check docs/engine-reference/godot/ before judging an API claim; flag API claims you cannot verify as [UNV] rather than wrong.' : ''}
Severity: BLOCKING only for defects that would make implementatio

on wrong or impossible. Return the schema.`

const cdPrompt = (s, main, specs, re) => `${CTX}

You are the creative-director, the SENIOR reviewer of the /design-review of ${P(s)} (read-only). ${re ? 'This is the RE-REVIEW after one revision pass.' : ''}
Main review: ${JSON.stringify(main)}
Specialist findings: ${JSON.stringify(specs)}
Synthesise these findings. What are the most important issues? Do you agree with the specialists? Spot-check the GDD sections the verdict turns on (Grep + Read by offset/limit). Verdict words (this skill's, never director-gate words): APPROVED (no blocking items remain), NEEDS REVISION (blocking items that targeted edits can fix), MAJOR REVISION NEEDED (the design itself is wrong — needs a rethink, not edits), NOT ASSESSED (the review could not be performed; say why).
Put only true blockers in required_before_implementation; list specialist disagreements (with each other or with you) explicitly in disagreements — do not silently resolve them. Every finding source-tagged in its text, e.g. "[systems-designer] ...". Return the schema.`

const fixPrompt = (s, cd) => `${CTX}

TASK: revise ${P(s)} to address the design-review findings (you are the only writer of this file now). Blocking: ${JSON.stringify(cd.required_before_implementation)}. Recommended: ${JSON.stringify(cd.recommended)}.
Rules: fix every BLOCKING item; apply RECOMMENDED items that are clear improvements and need no new creative direction. Precise edits with Edit (Grep the text, Read the range); never rewrite whole sections; keep the heading set and order. Mark each edited paragraph or row "*(Amended ${DATE} — design review)*". Keep the GDD consistent with itself: when you change a value, Grep the whole GDD for every other place it appears and update them all.
Registry: if you change a value or expression this GDD OWNS in design/registry/entities.yaml (source: ${P(s)}), do NOT edit the registry — return a registry_request. Never contradict a value another GDD owns; if a fix needs another system to change, add it to that GDD's... no — do not edit other GDDs: record it as a cross_gdd_note and as a row in this GDD's Open Questions.
If a blocker genuinely needs a creative or design decision only the user can make (changes a pillar, a user decision listed above, or the game's scope), do not guess: record it in Open Questions marked "USER DECISION" and return it in user_decisions. Decline (with reason) a finding that is wrong on inspection.
Return applied, declined, user_decisions, registry_requests, cross_gdd_notes.`

const logPrompt = (s, r) => `Append a review-log entry. Run in Bash: cd /d/the-synaptic-sea-2d && mkdir -p design/gdd/reviews && bash .claude/scripts/review-receipts.sh hash "${P(s)}" "design/registry/entities.yaml"
Then append (create the file with a first line "# Design Review Log — ${s}" and a blank line if absent) to design/gdd/reviews/${s}-review-log.md the entries below, each exactly in this format, then the hash command's output lines verbatim at the end of the LAST entry. Use python or a heredoc; preserve UTF-8. Do nothing else.
${r.entries.map(e => `## Review — ${DATE} — Verdict: ${e.verdict}
Scope signal: ${e.scope}
Specialists: ${e.specialists}
Blocking items: ${e.blocking.length} | Recommended: ${e.recommended.length}
Summary: ${e.summary}
Prior verdict resolved: ${e.prior}
Findings:
${e.blocking.length + e.recommended.length ? e.blocking.map(f => `- [BLOCKING] ${f.section}: ${f.finding}`).concat(e.recommended.map(f => `- [RECOMMENDED] ${f.section}: ${f.finding}`)).join('\n') : '- none'}`).join('\n\n')}
Return "ok" and the hash lines.`

log(`Full review of ${ALL.length} GDDs; up to ${MAX_SPEC} specialists each (extra domains are logged, not run)`)

const results = await pipeline(ALL,
  // Stage 1: main review
  s => agent(mainPrompt(s, null), { model: 'sonnet', effort: 'high', phase: 'Review', schema: MAIN_S, label: `main:${s}` }),
  // Stage 2: specialists in parallel + CD verdict
  async (main, s) => {
    if (!main) return { s, failed: 'main review' }
    let types = main.domains.filter((t, i, a) => SPEC_TYPES.includes(t) && a.indexOf(t) === i)
    for (const base of ['qa-lead', 'systems-designer', 'game-designer']) if (!types.includes(base)) types.unshift(base)
    const dropped = types.slice(MAX_SPEC); types = types.slice(0, MAX_SPEC)
    if (dropped.length) log(`${s}: specialists not run (cap ${MAX_SPEC}): ${dropped.join(', ')}`)
    const specs = await parallel(types.map(t => () => agent(specPrompt(s, t, main), { model: 'sonnet', effort: 'high', agentType: t, phase: 'Review', schema: SPEC_S, label: `${t}:${s}` })))
    const specOut = {}; types.forEach((t, i) => { specOut[t] = specs[i] || { failed: true } })
    const cd = await agent(cdPrompt(s, main, specOut, null), { model: 'opus', agentType: 'creative-director', phase: 'Review', schema: CD_S, label: `cd:${s}` })
    return { s, main, types, dropped, specOut, cd }
  },
  // Stage 3: revise once if NEEDS REVISION, then full lean re-review
  async (r) => {
    if (!r || r.failed || !r.cd) return r
    const s = r.s
    const first = { verdict: r.cd.verdict, scope: r.main.scope_signal, specialists: r.types.join(', '), blocking: r.cd.required_before_implementation, recommended: r.cd.recommended, summary: r.cd.synthesis.replace(/\n/g, ' ').slice(0, 700), prior: 'First review' }
    r.entries = [first]
    if (r.cd.verdict !== 'NEEDS REVISION') return r
    const fix = await agent(fixPrompt(s, r.cd), { model: 'sonnet', effort: 'high', phase: 'Revise', schema: FIX_S, label: `fix:${s}` })
    r.fix = fix
    if (!fix) return r
    const re = { blocking: r.cd.required_before_implementation, fixer: { applied: fix.applied, declined: fix.declined, user_decisions: fix.user_decisions } }
    const main2 = await agent(mainPrompt(s, re), { model: 'sonnet', effort: 'high', phase: 'Revise', schema: MAIN_S, label: `rereview:${s}` })
    if (!main2) return r
    const cd2 = await agent(cdPrompt(s, main2, { note: 'lean re-review: no specialists' }, true), { model: 'opus', agentType: 'creative-director', phase: 'Revise', schema: CD_S, label: `cd2:${s}` })
    r.main2 = main2; r.cd2 = cd2
    if (cd2) r.entries.push({ verdict: cd2.verdict, scope: main2.scope_signal, specialists: 'none (lean re-review)', blocking: cd2.required_before_implementation, recommended: cd2.recommended, summary: cd2.synthesis.replace(/\n/g, ' ').slice(0, 700), prior: cd2.required_before_implementation.length ? 'Partly' : 'Yes' })
    return r
  },
  // Stage 4: review log
  async (r) => {
    if (!r || r.failed || !r.entries) return r
    r.logged = await agent(logPrompt(r.s, r), { model: 'haiku', phase: 'Log', label: `log:${r.s}` })
    return r
  },
)

const out = ALL.map((s, i) => {
  const r = results[i]
  if (!r || r.failed) return { s, status: 'FAILED', why: r ? r.failed : 'pipeline error' }
  const finalCd = r.cd2 || r.cd
  return { s, first: r.cd ? r.cd.verdict : 'none', final: finalCd ? finalCd.verdict : 'none', specialists: r.types, dropped: r.dropped,
    blocking_left: finalCd ? finalCd.required_before_implementation.map(f => `${f.section}: ${f.finding}`) : [],
    disagreements: finalCd ? finalCd.disagreements : [],
    user_decisions: r.fix ? r.fix.user_decisions : [], registry_requests: r.fix ? r.fix.registry_requests : [], cross_gdd_notes: r.fix ? r.fix.cross_gdd_notes : [],
    applied: r.fix ? r.fix.applied.length : 0, scope: r.main ? r.main.scope_signal : '?', missing_deps: r.main ? r.main.dependency_graph.filter(d => !d.exists).map(d => d.system) : [], logged: !!r.logged }
})
const tally = {}; out.forEach(o => { tally[o.final] = (tally[o.final] || 0) + 1 })
log(`final verdicts: ${JSON.stringify(tally)}`)
return { tally, out }

