input.script:
export const meta = {
  name: 'rereview-fix-pass',
  description: 'Apply the 26 re-review findings with delegated rulings R1-R11: per-GDD fixers (chained where numbers depend), grep-verify residuals, then one serial registry pass',
  phases: [
    { title: 'Fix', detail: 'per-GDD fixer; Attention->Boarding->Derelict on Opus, Suit->Web Map chained' },
    { title: 'Verify', detail: 'Haiku residual grep per GDD; finisher on residuals' },
    { title: 'Registry', detail: 'one serial agent applies all registry requests' },
  ],
}
const TAIL = 'C:/Users/dasbl/AppData/Local/Temp/claude/D--the-synaptic-sea-2d/e887ccb9-1186-40d9-9566-5eacccbd9b44/scratchpad/tail/'
const ALL = ['command-simulation-layer','pixel-perfect-render-pipeline-camera','player-controller-input','life-support-graph','save-load-and-versioned-format','item-and-module-database','emitter-state-and-light-exposure-query','failure-and-trail-system','2d-lighting-and-occlusion','interaction-system','suit-and-equipment','ship-section-and-layout-data-model','ship-body-and-interior-physics','derelict-authoring-handmade-kits','attention-system','modular-ship-assembly','web-map-and-transit','horror-entities','sanity-and-hallucination-rules','boarding-and-salvage','perception-filter','chart-table-web-map-and-menus','adaptive-audio-and-tells','hud-and-suit-layer','in-world-instruments-and-inspect-view','debug-overlay-true-values']
const CHAINS = [['attention-system','boarding-and-salvage','derelict-authoring-handmade-kits'], ['suit-and-equipment','web-map-and-transit']]
const OPUS = ['attention-system','boarding-and-salvage','derelict-authoring-handmade-kits']
const chained = CHAINS.flat()
const P = s => `design/gdd/${s}.md`

const CTX = `PROJECT: The Synaptic Sea — Godot 4.7.2 / GDScript, 2D HD-pixel-art co-op survival horror. Repo D:/the-synaptic-sea-2d (Bash: cd /d/the-synaptic-sea-2d). workflow tier full.
READ RULES: GDDs are 150-370 KB; a hook refuses whole-file Read over 40 KB. Grep "^#" (content, -n) for headings, Grep for the text you need, Read ranges by offset/limit.
Registry: design/registry/entities.yaml — an entry's source: GDD owns the value. Never edit the registry yourself.
RULINGS: Read ${TAIL}rr-rulings.md in full FIRST. It holds general rules G1-G5 and delegated rulings R1-R11 (the user delegated these calls). They are binding. Prior "Resolved ... user ruling" markers in the GDD are binding too — never reverse one.`

const FIX_S = { type: 'object', properties: {
  applied: { type: 'array', items: { type: 'string' } }, declined: { type: 'array', items: { type: 'string' } },
  residual_checks: { type: 'array', items: { type: 'object', properties: { old_text: { type: 'string' }, blocker: { type: 'string' } }, required: ['old_text', 'blocker'] } },
  registry_requests: { type: 'array', items: { type: 'object', properties: { name: { type: 'string' }, change: { type: 'string' }, reason: { type: 'string' } }, required: ['name', 'change', 'reason'] } },
  cross_gdd_notes: { type: 'array', items: { type: 'string' } }, user_decisions: { type: 'array', items: { type: 'string' } } },
  required: ['applied', 'declined', 'residual_checks', 'registry_requests', 'cross_gdd_notes', 'user_decisions'] }
const VER_S = { type: 'object', properties: { residuals: { type: 'array', items: { type: 'object', properties: { old_text: { type: 'string' }, lines: { type: 'string' }, blocker: { type: 'string' } }, required: ['old_text', 'lines', 'blocker'] } } }, required: ['residuals'] }

const fixPrompt = (s, upstream) => `${CTX}

TASK: revise ${P(s)} (you are its only writer now) to resolve its re-review findings. Read ${TAIL}rr/${s}.json: "blocking" (must all be fixed), "recommended" (apply each that is a clear improvement and needs no new creative direction), "disagreements" (resolve per G2).
${upstream ? `UPSTREAM: these GDDs in your numeric chain were just revised; quote their current values (Grep them now), do not re-derive what they own: ${JSON.stringify(upstream)}` : ''}
Rules:
- Precise Edit calls (Grep the text, Read the range); never rewrite whole sections; keep heading set and order. Mark each edited paragraph/row "*(Amended 2026-10-27 — re-review)*", or "*(Amended 2026-10-27 — re-review, delegated ruling Rn)*" when applying a ruling.
- When you change a value or name, Grep the WHOLE GDD for every occurrence (examples, variable tables, ACs, Tuning Knobs, Edge Cases, Open Questions, Cross-References) and update all of them (G3).
- Other GDDs: do not edit them. Where your fix requires a sibling to change, and the rulings sheet does not already direct that sibling, record a cross_gdd_note and an Open Questions row.
- Registry: for any registered value, name, formula or source owner this GDD changes, return a registry_request (name, exact change, reason). Do not edit entities.yaml.
- residual_checks: for EVERY blocking item, list 1-3 short verbatim snippets of the OLD wrong text (as it appeared before your edit, 15-80 chars, distinctive) whose absence proves the fix landed.
- user_decisions: only for a call that would reverse a user ruling or set X14; record it in Open Questions marked "USER DECISION". Everything else you decide per the rulings.
- Decline (with reason) a finding that is wrong on inspection.
Return the schema.`

const verPrompt = (s, fix) => `Repo D:/the-synaptic-sea-2d. Read-only. For each snippet below, run Grep (fixed string; output_mode content, -n) on design/gdd/${s}.md and report every snippet that still occurs, with its line numbers. A snippet that occurs only inside a line containing "was:" or "(was " or "superseded" or "Amended" history wording counts as resolved — skip it. Snippets: ${JSON.stringify(fix.residual_checks)}
Return residuals (empty array if none).`

const finPrompt = (s, ver) => `${CTX}

TASK: these residuals of already-ruled fixes remain in ${P(s)} — old wrong text still present (the fix was applied elsewhere in the doc but not here). For each, Read the surrounding lines, and conform it to the fixed version used elsewhere in the GDD (Grep for the "*(Amended 2026-10-27 — re-review" markers to find the fixed text). Same edit rules: Edit only this GDD, mark "*(Amended 2026-10-27 — re-review)*". Residuals: ${JSON.stringify(ver.residuals)}
Return the schema (residual_checks may be empty; registry_requests only if needed).`

async function fixOne(s, upstream) {
  const model = OPUS.includes(s) ? 'opus' : 'sonnet'
  const fix = await agent(fixPrompt(s, upstream), { model, effort: 'high', phase: 'Fix', schema: FIX_S, label: `fix:${s}` })
  if (!fix) return { s, failed: 'fixer' }
  let ver = null, fin = null
  if (fix.residual_checks.length) {
    ver = await agent(verPrompt(s, fix), { model: 'haiku', phase: 'Verify', schema: VER_S, label: `verify:${s}` })
    if (ver && ver.residuals.length) fin = await agent(finPrompt(s, ver), { model: 'sonnet', effort: 'high', phase: 'Verify', schema: FIX_S, label: `finish:${s}` })
  }
  return { s, fix, residuals: ver ? ver.residuals.length : null, fin }
}

const tasks = ALL.filter(s => !chained.includes(s)).map(s => () => fixOne(s, null))
for (const chain of CHAINS) tasks.push(async () => {
  const out = []; const up = []
  for (const s of chain) {
    const r = await fixOne(s, up.length ? up.slice() : null)
    out.push(r)
    if (r.fix) up.push({ gdd: P(s), applied: r.fix.applied.slice(0, 40) })
  }
  return out
})
const res = (await parallel(tasks)).flat().filter(Boolean)

phase('Registry')
const reqs = res.filter(r => r.fix).flatMap(r => [...r.fix.registry_requests, ...((r.fin && r.fin.registry_requests) || [])].map(q => ({ gdd: P(r.s), ...q })))
log(`registry requests: ${reqs.length}`)
let reg = null
if (reqs.length) reg = await agent(`Repo D:/the-synaptic-sea-2d (Bash: cd /d/the-synaptic-sea-2d). You are the ONLY writer of design/registry/entities.yaml (huge file — Grep "name: <NAME>" -n then Read ranges by offset/limit; never read it whole).
Apply these registry requests from GDD fixers serially: ${JSON.stringify(reqs)}
Conventions: sections in order entities/items/formulas/constants; each entry "  - name: X" with status, source (owning GDD), referenced_by (block list), attributes, added/revised. For a changed value set "revised: 2026-10-27" and add "# was: <old> before 2026-10-27" on the line above the changed field. Never delete an entry; retired ones get "status: deprecated". A new entry goes after the LAST REAL entry of its section (never after trailing column-0 comment blocks). Quote any scalar containing ": ", " #", or starting with a special character. Before applying a request, verify against the requesting GDD's current text (Grep it) that the change is what the GDD now says; decline requests that would change a value another GDD owns (source:) unless the request comes from the owner, or the request is a ruling R1 source move. Verify only by Grep; after all edits run: bash .claude/scripts/registry.sh validate 2>&1 | tail -5 (if the script exists) and report.
Return a short report: applied N, declined (name: reason), validate output.`, { model: 'opus', phase: 'Registry', label: 'registry' })

return { reg, out: res.map(r => ({ s: r.s, failed: r.failed || null, applied: r.fix ? r.fix.applied.length : 0, declined: r.fix ? r.fix.declined : [], residuals_after_fix: r.residuals, finisher: r.fin ? r.fin.applied.length : null, cross: r.fix ? r.fix.cross_gdd_notes : [], user: r.fix ? r.fix.user_decisions : [], regreq: r.fix ? r.fix.registry_requests.length : 0 })) }
